double kB = 1.0; // Boltzmann constant in consistent units
double collisionProb = 1.0 - std::exp(-collisionFreq * dt);
static thread_local std::mt19937 gen(std::random_device{}());
std::uniform_real_distribution<double> uniformDist(0.0, 1.0);
for (std::size_t i = 0; i < velocities.size(); ++i) {
    if (uniformDist(gen) < collisionProb) {
        double sigma = std::sqrt(kB * targetTemp / masses[i]);
        std::normal_distribution<double> normalDist(0.0, sigma);
        velocities[i].x = normalDist(gen);
        velocities[i].y = normalDist(gen);
        velocities[i].z = normalDist(gen);
    }
}

